
function PagingToolbarSelections(a){return Ext.apply(this,a)}PagingToolbarSelections.prototype=new Object;PagingToolbarSelections.prototype.saveSelectionsOnPage=function(b){for(var a in b){if(b[a].page==this.activePage){return b[a].selections=this.selections}}return b.push({page:this.activePage,selections:this.selections})};PagingToolbarSelections.prototype.setSelectionsOnPage=function(c,b){for(var a=0;a<c.length;a++){if(c[a].page==this.activePage){b.getSelectionModel().selectRows(this.getIndexSelectionsOnPage(b.getStore(),c[a].selections))}}};PagingToolbarSelections.prototype.getIndexSelectionsOnPage=function(a,c){indexRows=new Array();for(var b=0;b<c.length;b++){indexRows.push(a.find("id",c[b].data.id))}return indexRows};PagingToolbarSelections.prototype.getSelectionsOnArray=function(a){selectionsOnArray=new Array();arrayList=new Array();arrayList=this.saveSelectionsOnPage(a);for(i=0;i<a.length;i++){for(j=0;j<a[i].selections.length;j++){selectionsOnArray.push(a[i].selections[j].data)}}return selectionsOnArray};